		while (scan1.hasNext()) {
			String[] satir = scan1.next().split(":");
			Ogrenci ogrenci = new Ogrenci(satir[0], satir[1], Integer.valueOf(satir[2].trim()));
			ogrenciler.add(ogrenci);
		}

		return ogrenciler;
	}

