public static void forEachKullanımı() {
	ArrayList<String> liste = new ArrayList<>();
	liste.add("A");
	liste.add("B");
	liste.add("C");

	// for-each döngüsü
	for (String eleman : liste) {
		System.out.println(eleman);
	}

